package com.fasterxml.jackson.core.io;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for NumberInput.parseBigDecimal(char[] buffer, int offset, int len)
 */
public class NumberInput_parseBigDecimal_TriageGen1Test {

    @Test
    public void testParseBigDecimal_PositiveInteger() {
        char[] buffer = "12345".toCharArray();
        BigDecimal result = NumberInput.parseBigDecimal(buffer, 0, 5);
        assertEquals(new BigDecimal("12345"), result);
    }

    @Test
    public void testParseBigDecimal_NegativeInteger() {
        char[] buffer = "-12345".toCharArray();
        BigDecimal result = NumberInput.parseBigDecimal(buffer, 0, 6);
        assertEquals(new BigDecimal("-12345"), result);
    }

    @Test
    public void testParseBigDecimal_WithDecimal() {
        char[] buffer = "123.456".toCharArray();
        BigDecimal result = NumberInput.parseBigDecimal(buffer, 0, 7);
        assertEquals(new BigDecimal("123.456"), result);
    }

    @Test
    public void testParseBigDecimal_WithOffset() {
        // Test parsing "456" from "123456" starting at index 3
        char[] buffer = "123456".toCharArray();
        BigDecimal result = NumberInput.parseBigDecimal(buffer, 3, 3);
        assertEquals(new BigDecimal("456"), result);
    }

    @Test
    public void testParseBigDecimal_WithScientificNotation() {
        char[] buffer = "1.23E4".toCharArray();
        BigDecimal result = NumberInput.parseBigDecimal(buffer, 0, 6);
        // 1.23 * 10^4 = 12300
        assertEquals(new BigDecimal("12300"), result.stripTrailingZeros());
    }

    @Test
    public void testParseBigDecimal_LeadingZero() {
        char[] buffer = "000123.45".toCharArray();
        BigDecimal result = NumberInput.parseBigDecimal(buffer, 0, 9);
        assertEquals(new BigDecimal("123.45"), result);
    }

    @Test
    public void testParseBigDecimal_Zero() {
        char[] buffer = "0".toCharArray();
        BigDecimal result = NumberInput.parseBigDecimal(buffer, 0, 1);
        assertEquals(BigDecimal.ZERO, result);
    }

    @Test(expected = NumberFormatException.class)
    public void testParseBigDecimal_InvalidFormat_Letters() {
        char[] buffer = "123a45".toCharArray();
        NumberInput.parseBigDecimal(buffer, 0, 6);
    }

    @Test(expected = NumberFormatException.class)
    public void testParseBigDecimal_InvalidFormat_MultipleDots() {
        char[] buffer = "12.34.56".toCharArray();
        NumberInput.parseBigDecimal(buffer, 0, 8);
    }

    @Test(expected = NumberFormatException.class)
    public void testParseBigDecimal_EmptyRange() {
        char[] buffer = "".toCharArray();
        // len 0 might throw exception depending on BigDecimal implementation
        NumberInput.parseBigDecimal(buffer, 0, 0);
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testParseBigDecimal_OutOfBoundsOffset() {
        char[] buffer = "123".toCharArray();
        NumberInput.parseBigDecimal(buffer, 5, 1);
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testParseBigDecimal_OutOfBoundsLen() {
        char[] buffer = "123".toCharArray();
        NumberInput.parseBigDecimal(buffer, 0, 10);
    }
}
